<?php require_once __DIR__.'/_helpers.php'; $current_page_override='v_dataparkir.php'; $basePath=base_url(); ?><!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kendaraan Masuk - SiParkir</title><link rel="stylesheet" href="<?=e($basePath.'/asset/dashboard_admin.css')?>"></head><body><div class="layout"><?php include __DIR__.'/_sidebar.php'; ?><main class="main"><header class="header"><div><p class="small-title">PARKING MANAGEMENT</p><h1>Kendaraan Masuk</h1><p class="subtitle">Catat kendaraan masuk, tarif, dan area parkir.</p></div></header><section class="page-panel form-panel"><form method="post" action="<?=e($basePath.'/controller/c_dataparkir.php?aksi=proses_masuk')?>" class="form-grid"><div class="form-group"><label>Kendaraan</label><select class="form-select" name="id_kendaraan" required><option value="">-- Pilih Kendaraan --</option><?php foreach($kendaraan as $k):?><option value="<?=$k['id_kendaraan']?>"><?=e($k['plat_nomor'].' - '.ucfirst($k['jenis_kendaraan']).' - '.$k['pemilik'])?></option><?php endforeach;?></select><?php if(empty($kendaraan)):?><small class="help">Semua kendaraan sedang parkir atau belum terdaftar.</small><?php endif;?></div><div class="form-group"><label>Tarif</label><select class="form-select" name="id_tarif" required><?php foreach($tarif as $t):?><option value="<?=$t['id_tarif']?>"><?=e(ucfirst($t['jenis_kendaraan']).' - '.rupiah($t['tarif_per_jam']).'/jam')?></option><?php endforeach;?></select></div><div class="form-group"><label>Area Parkir</label><select class="form-select" name="id_area" required><option value="">-- Pilih Area --</option><?php foreach($area as $a):?><option <?=$a['terisi']>=$a['kapasitas']?'disabled':''?> value="<?=$a['id_area']?>"><?=e($a['nama_area'].' ('.$a['terisi'].'/'.$a['kapasitas'].')')?></option><?php endforeach;?></select></div><div class="form-actions"><button class="btn-primary" <?=$kendaraan?'':'disabled'?>>Simpan Kendaraan Masuk</button><a class="btn-secondary" href="<?=e($basePath.'/controller/c_dataparkir.php?aksi=tampil')?>">Kembali</a></div></form></section></main></div></body></html>
